#!/usr/bin/env node
/**
 * evolution-auto-runner.cjs — SessionStart hook
 * Auto-triggers Python evolution scripts when staleness thresholds exceeded.
 *
 * 4 checks:
 *   1. auto_evolve.py — knowledge hunting + integration (>7 days)
 *   2. scheduled-evolution-loop.py — prompt evolution proposals (>7 days)
 *   3. batch-auto-verify.py — expired prediction verification (>3 days)
 *   4. knowledge_hunter.py — external data hunting (>14 days)
 *
 * All processes spawned detached + unref'd. Fail-open (exit 0 always).
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

let isHookEnabled;
try {
  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
} catch {
  isHookEnabled = () => true;
}

if (!isHookEnabled('evolution-auto-runner')) {
  process.exit(0);
}

const DEBUG = !!process.env.CK_DEBUG;
const REPO_ROOT = path.resolve(__dirname, '..', '..');
const LOG_DIR = path.join(__dirname, '.logs');
const LOG_FILE = path.join(LOG_DIR, 'evolution-auto-runner.log');
const PYTHON_EXE = path.join(REPO_ROOT, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');

const LOCK_EXPIRY_MS = 600000; // 10 minutes

const SCRIPTS = {
  autoEvolve: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'deep-intelligence', 'auto_evolve.py'),
  scheduledEvolution: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'compound', 'scheduled-evolution-loop.py'),
  batchVerify: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'feedback_loop', 'batch-auto-verify.py'),
  knowledgeHunter: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'deep-intelligence', 'knowledge_hunter.py'),
  metaEvolution: path.join(REPO_ROOT, '.claude', 'lib', 'intelligence', 'mechanism', 'meta_evolution_orchestrator.py'),
};

const DATA_FILES = {
  evolutionLog: path.join(REPO_ROOT, 'data', 'deep-intelligence', 'evolution_log.json'),
  evolutionConfig: path.join(REPO_ROOT, '.claude', 'data', 'evolution-config.json'),
  pendingIndex: path.join(REPO_ROOT, 'data', 'predictions', 'pending-index.json'),
  batchVerifyMarker: path.join(LOG_DIR, 'batch-verify-last-run.txt'),
  knowledgeHuntMarker: path.join(LOG_DIR, 'knowledge-hunt-last-run.txt'),
};

function ensureLogDir() {
  if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });
}

function log(msg) {
  ensureLogDir();
  const line = `[${new Date().toISOString()}] ${msg}\n`;
  fs.appendFileSync(LOG_FILE, line);
  if (DEBUG) console.error(`[evolution-auto-runner] ${msg}`);
}

function readJson(filepath) {
  try {
    return JSON.parse(fs.readFileSync(filepath, 'utf8'));
  } catch {
    return null;
  }
}

function lockPath(name) {
  return path.join(LOG_DIR, `evolution-${name}.lock`);
}

function isLocked(name) {
  const lp = lockPath(name);
  if (!fs.existsSync(lp)) return false;
  try {
    const data = JSON.parse(fs.readFileSync(lp, 'utf8'));
    return (Date.now() - new Date(data.started).getTime()) < LOCK_EXPIRY_MS;
  } catch {
    return false;
  }
}

function acquireLock(name) {
  ensureLogDir();
  fs.writeFileSync(lockPath(name), JSON.stringify({
    started: new Date().toISOString(),
    pid: process.pid
  }));
}

function releaseLock(name) {
  try { fs.unlinkSync(lockPath(name)); } catch {}
}

function spawnDetached(name, scriptPath, args) {
  if (!fs.existsSync(PYTHON_EXE)) {
    log(`SKIP ${name}: python venv not found at ${PYTHON_EXE}`);
    return false;
  }
  if (!fs.existsSync(scriptPath)) {
    log(`SKIP ${name}: script not found at ${scriptPath}`);
    return false;
  }
  if (isLocked(name)) {
    log(`SKIP ${name}: already running (locked)`);
    return false;
  }

  acquireLock(name);

  try {
    const logOut = path.join(LOG_DIR, `${name}-stdout.log`);
    const logErr = path.join(LOG_DIR, `${name}-stderr.log`);
    const out = fs.openSync(logOut, 'a');
    const err = fs.openSync(logErr, 'a');

    const child = spawn(PYTHON_EXE, [scriptPath, ...args], {
      cwd: REPO_ROOT,
      detached: true,
      stdio: ['ignore', out, err],
      windowsHide: true,
    });

    child.on('close', () => releaseLock(name));
    child.unref();

    log(`SPAWNED ${name} (pid=${child.pid})`);
    return true;
  } catch (e) {
    log(`ERROR ${name}: ${e.message}`);
    releaseLock(name);
    return false;
  }
}

function daysSince(isoString) {
  if (!isoString) return Infinity;
  try {
    return (Date.now() - new Date(isoString).getTime()) / 86400000;
  } catch {
    return Infinity;
  }
}

function daysSinceFile(filepath) {
  try {
    const content = fs.readFileSync(filepath, 'utf8').trim();
    return daysSince(content);
  } catch {
    return Infinity;
  }
}

function writeMarker(filepath) {
  ensureLogDir();
  fs.writeFileSync(filepath, new Date().toISOString());
}

// --- Check 1: Auto-evolve (knowledge hunting + integration) ---
function checkAutoEvolve() {
  const data = readJson(DATA_FILES.evolutionLog);
  if (!data) {
    log('CHECK auto-evolve: no evolution_log.json, triggering first run');
    return spawnDetached('auto-evolve', SCRIPTS.autoEvolve, []);
  }

  const cycles = data.cycles || [];
  const lastCycle = cycles.length > 0 ? cycles[cycles.length - 1] : null;
  const lastTs = lastCycle ? lastCycle.timestamp : null;
  const days = daysSince(lastTs);

  if (days > 7) {
    log(`CHECK auto-evolve: ${days.toFixed(1)} days since last cycle, triggering`);
    return spawnDetached('auto-evolve', SCRIPTS.autoEvolve, []);
  }

  log(`CHECK auto-evolve: ${days.toFixed(1)} days ago, skipping (threshold=7)`);
  return false;
}

// --- Check 2: Scheduled evolution loop ---
function checkScheduledEvolution() {
  const config = readJson(DATA_FILES.evolutionConfig);
  const lastRun = config ? config.last_run : null;
  const days = daysSince(lastRun);

  if (days > 7) {
    log(`CHECK scheduled-evolution: ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last run, triggering`);
    return spawnDetached('scheduled-evolution', SCRIPTS.scheduledEvolution, []);
  }

  log(`CHECK scheduled-evolution: ${days.toFixed(1)} days ago, skipping (threshold=7)`);
  return false;
}

// --- Check 3: Batch prediction verification ---
function checkBatchVerify() {
  const pending = readJson(DATA_FILES.pendingIndex);
  if (!pending || !Array.isArray(pending) || pending.length === 0) {
    log('CHECK batch-verify: no pending predictions, skipping');
    return false;
  }

  const now = Date.now();
  const hasExpired = pending.some(p => {
    if (!p.deadline) return false;
    return new Date(p.deadline).getTime() < now;
  });

  if (!hasExpired) {
    log('CHECK batch-verify: no expired predictions, skipping');
    return false;
  }

  const days = daysSinceFile(DATA_FILES.batchVerifyMarker);

  if (days > 3) {
    log(`CHECK batch-verify: expired predictions found, ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last verify, triggering`);
    writeMarker(DATA_FILES.batchVerifyMarker);
    return spawnDetached('batch-verify', SCRIPTS.batchVerify, ['--all-expired']);
  }

  log(`CHECK batch-verify: ${days.toFixed(1)} days ago, skipping (threshold=3)`);
  return false;
}

// --- Check 4: Knowledge hunter (external data) ---
function checkKnowledgeHunt() {
  const days = daysSinceFile(DATA_FILES.knowledgeHuntMarker);

  if (days > 14) {
    log(`CHECK knowledge-hunt: ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last hunt, triggering`);
    writeMarker(DATA_FILES.knowledgeHuntMarker);
    return spawnDetached('knowledge-hunt', SCRIPTS.knowledgeHunter, []);
  }

  log(`CHECK knowledge-hunt: ${days.toFixed(1)} days ago, skipping (threshold=14)`);
  return false;
}

// --- Check 5: Meta-evolution orchestrator (AEVO outer loop) ---
function checkMetaEvolution() {
  const statePath = path.join(REPO_ROOT, 'data', 'config', 'meta-edit-controller-state.json');
  const outcomesPath = path.join(REPO_ROOT, 'data', 'calibration', 'outcomes.jsonl');

  if (!fs.existsSync(outcomesPath)) {
    log('CHECK meta-evolution: no outcomes file, skipping');
    return false;
  }

  const state = readJson(statePath);
  if (state && state.status === 'segment_running') {
    log('CHECK meta-evolution: segment running, triggering check');
    return spawnDetached('meta-evolution', SCRIPTS.metaEvolution, ['--mode', 'session_start']);
  }

  try {
    const lines = fs.readFileSync(outcomesPath, 'utf8').trim().split('\n').filter(Boolean);
    const lastEditTime = state ? state.last_edit_time || '' : '';
    const outcomesSince = lastEditTime
      ? lines.filter(l => { try { return JSON.parse(l).timestamp > lastEditTime; } catch { return false; } }).length
      : lines.length;

    if (outcomesSince >= 5) {
      log(`CHECK meta-evolution: ${outcomesSince} outcomes since last edit, triggering`);
      return spawnDetached('meta-evolution', SCRIPTS.metaEvolution, ['--mode', 'session_start']);
    }

    log(`CHECK meta-evolution: ${outcomesSince} outcomes since last edit, skipping (threshold=5)`);
  } catch (e) {
    log(`CHECK meta-evolution: error reading outcomes: ${e.message}`);
  }

  return false;
}

// --- Main ---
try {
  ensureLogDir();
  log('--- Evolution auto-runner starting ---');

  let spawned = 0;
  if (checkAutoEvolve()) spawned++;
  if (checkScheduledEvolution()) spawned++;
  if (checkBatchVerify()) spawned++;
  if (checkKnowledgeHunt()) spawned++;
  if (checkMetaEvolution()) spawned++;

  if (spawned > 0) {
    console.log(`🧬 Auto-evolution: ${spawned} background task(s) spawned`);
  }

  log(`--- Done: ${spawned} task(s) spawned ---`);
} catch (e) {
  try { log(`CRASH: ${e.message}`); } catch {}
  if (DEBUG) console.error(`[evolution-auto-runner] ${e.message}`);
}

process.exit(0);

"""
meta_edit_controller.py — The AEVO outer loop for mechanism self-evolution.

State machine: IDLE → OBSERVING → EDITING → SEGMENT_RUNNING → EVALUATING → IDLE

Called after every Nth outcome (default 5). Reads mechanism errors, proposes
knob edits via Bayesian updater, applies within safety bounds, tracks segment,
evaluates keep/revert/amplify.

Usage:
    controller = MetaEditController()
    result = controller.run()
    # result.action in: "no_edit", "edit_applied", "segment_evaluated", "segment_running"
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass, asdict
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

from .knob_registry import KnobRegistry, KnobValidationError
from .error_attributor import ErrorAttributor
from .bayesian_knob_updater import BayesianKnobUpdater, KnobEdit
from .segment_evaluator import SegmentEvaluator, EvalDecision
from .safety_harness import SafetyHarness

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[4]
_DEFAULT_CONTROLLER_STATE = _REPO_ROOT / "data" / "config" / "meta-edit-controller-state.json"
_DEFAULT_BRIER_PATH = _REPO_ROOT / "data" / "calibration" / "brier-scores.jsonl"


@dataclass
class MetaEditResult:
    action: str  # no_edit, edit_applied, segment_evaluated, segment_running, error
    reason: str = ""
    edit: Optional[dict] = None
    eval_decision: Optional[dict] = None
    segment_id: str = ""

    def to_dict(self) -> dict:
        return {
            "action": self.action,
            "reason": self.reason,
            "edit": self.edit,
            "eval_decision": self.eval_decision,
            "segment_id": self.segment_id,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }


class MetaEditController:
    """
    The outer-loop meta-edit controller.

    Observes mechanism errors, proposes edits, runs evaluation segments,
    and decides keep/revert/amplify — all deterministically, no LLM.
    """

    def __init__(
        self,
        registry: Optional[KnobRegistry] = None,
        attributor: Optional[ErrorAttributor] = None,
        evaluator: Optional[SegmentEvaluator] = None,
        updater: Optional[BayesianKnobUpdater] = None,
        harness: Optional[SafetyHarness] = None,
        state_path: Optional[Path] = None,
        brier_path: Optional[Path] = None,
        min_errors_to_propose: int = 3,
        trigger_interval: int = 5,
    ):
        self.registry = registry or KnobRegistry()
        self.attributor = attributor or ErrorAttributor()
        self.evaluator = evaluator or SegmentEvaluator()
        self.updater = updater or BayesianKnobUpdater(self.registry)
        self.harness = harness or SafetyHarness()
        self.state_path = Path(state_path or _DEFAULT_CONTROLLER_STATE)
        self.brier_path = Path(brier_path or _DEFAULT_BRIER_PATH)
        self.min_errors_to_propose = min_errors_to_propose
        self.trigger_interval = trigger_interval

    def run(self) -> MetaEditResult:
        """
        Main entry point. Called after every Nth outcome.

        State machine:
        1. If segment running → check if ready → evaluate
        2. If idle → observe errors → propose edit → apply → start segment
        """
        state = self._load_state()

        if state.get("status") == "segment_running":
            return self._handle_running_segment(state)

        return self._handle_idle(state)

    def should_run(self, outcome_count: int) -> bool:
        """Check if controller should run based on outcome count."""
        return outcome_count > 0 and outcome_count % self.trigger_interval == 0

    def _handle_running_segment(self, state: dict) -> MetaEditResult:
        """Check active segment and evaluate if ready."""
        segment_id = state.get("segment_id", "")
        if not segment_id:
            self._reset_state()
            return MetaEditResult(action="error", reason="corrupt state: no segment_id")

        result = self.evaluator.check_segment(segment_id)

        if not result.ready:
            return MetaEditResult(
                action="segment_running",
                reason=f"{result.verdicts_collected}/{result.verdicts_needed} verdicts collected",
                segment_id=segment_id,
            )

        decision = self.evaluator.evaluate(segment_id)
        if decision is None:
            self._reset_state()
            return MetaEditResult(action="error", reason="evaluation failed")

        self._apply_eval_decision(decision)

        self._update_state(status="idle", segment_id="")

        return MetaEditResult(
            action="segment_evaluated",
            reason=decision.reason,
            eval_decision=decision.to_dict(),
            segment_id=segment_id,
        )

    def _handle_idle(self, state: dict) -> MetaEditResult:
        """Observe errors, propose edit, apply, start segment."""
        knob_errors = self._observe_errors(state)
        if not knob_errors:
            return MetaEditResult(action="no_edit", reason="no mechanism errors found")

        top_knob, its_errors = max(
            knob_errors.items(), key=lambda x: len(x[1])
        )

        if len(its_errors) < self.min_errors_to_propose:
            return MetaEditResult(
                action="no_edit",
                reason=f"only {len(its_errors)} errors for {top_knob} "
                       f"(need {self.min_errors_to_propose})",
            )

        edit = self.updater.propose_edit(top_knob, its_errors)
        if edit is None:
            return MetaEditResult(
                action="no_edit",
                reason=f"Bayesian updater found no actionable edit for {top_knob}",
            )

        knob_range = self.registry.get_range(edit.knob_id)
        safety = self.harness.validate_edit(
            edit.knob_id, edit.old_value, edit.new_value,
            knob_range=knob_range, source="meta_edit_controller",
        )
        if not safety.allowed:
            reasons = "; ".join(v.message for v in safety.violations)
            logger.warning("Safety harness blocked edit %s: %s", edit.knob_id, reasons)
            return MetaEditResult(action="no_edit", reason=f"safety blocked: {reasons}")

        try:
            self.registry.set(
                edit.knob_id,
                edit.new_value,
                reason=f"meta-edit: {edit.evidence_count} errors, "
                       f"avg_sev={edit.avg_severity:.2f}, conf={edit.confidence:.2f}",
                source="meta_edit_controller",
            )
        except (KnobValidationError, KeyError) as e:
            return MetaEditResult(action="error", reason=f"edit rejected: {e}")

        brier_before = self._get_recent_brier_avg()
        segment_id = self.evaluator.start_segment(edit.to_dict(), brier_before)

        self._update_state(
            status="segment_running",
            segment_id=segment_id,
            last_edit=edit.to_dict(),
            last_edit_time=datetime.now(timezone.utc).isoformat(),
        )

        logger.info("Meta-edit applied: %s %s → %s (segment=%s)",
                     edit.knob_id, edit.old_value, edit.new_value, segment_id)

        return MetaEditResult(
            action="edit_applied",
            reason=edit.reason,
            edit=edit.to_dict(),
            segment_id=segment_id,
        )

    def _observe_errors(self, state: dict) -> dict[str, list[dict]]:
        """Group recent mechanism errors by knob."""
        last_edit_time = state.get("last_edit_time")
        all_errors = self.attributor.load_errors(n=100)

        if last_edit_time:
            all_errors = [
                e for e in all_errors
                if e.get("timestamp", "") > last_edit_time
            ]

        knob_groups: dict[str, list[dict]] = {}
        for err in all_errors:
            for knob in err.get("knobs_implicated", []):
                knob_groups.setdefault(knob, []).append(err)

        return knob_groups

    def _apply_eval_decision(self, decision: EvalDecision):
        """Apply keep/revert/amplify decision."""
        if decision.decision == "REVERT":
            try:
                self.registry.set(
                    decision.knob_id,
                    decision.old_value,
                    reason=f"meta-revert: Brier worsened {decision.brier_delta_pct:+.1%}",
                    source="meta_edit_controller",
                )
                logger.info("Reverted %s to %s", decision.knob_id, decision.old_value)
            except (KnobValidationError, KeyError) as e:
                logger.error("Revert failed for %s: %s", decision.knob_id, e)

        elif decision.decision == "AMPLIFY":
            current = self.registry.get(decision.knob_id)
            original_delta = decision.new_value - decision.old_value
            amplified = current + original_delta
            try:
                self.registry.set(
                    decision.knob_id,
                    amplified,
                    reason=f"meta-amplify: Brier improved {abs(decision.brier_delta_pct):.1%}",
                    source="meta_edit_controller",
                )
                logger.info("Amplified %s: %s → %s", decision.knob_id, current, amplified)
            except (KnobValidationError, KeyError) as e:
                logger.info("Amplify capped for %s: %s (keeping current)", decision.knob_id, e)

        self.evaluator.clear_segment()

    def _get_recent_brier_avg(self, n: int = 10) -> float:
        """Get average Brier score from recent verdicts."""
        if not self.brier_path.exists():
            return 0.5

        scores = []
        try:
            for line in self.brier_path.read_text(encoding="utf-8").strip().split("\n"):
                if not line.strip():
                    continue
                record = json.loads(line)
                score = record.get("brier_score", record.get("score"))
                if score is not None:
                    scores.append(float(score))
        except (json.JSONDecodeError, OSError, ValueError):
            return 0.5

        if not scores:
            return 0.5

        return sum(scores[-n:]) / len(scores[-n:])

    def _load_state(self) -> dict:
        if not self.state_path.exists():
            return {"status": "idle"}
        try:
            return json.loads(self.state_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return {"status": "idle"}

    def _update_state(self, **kwargs):
        state = self._load_state()
        state.update(kwargs)
        self.state_path.parent.mkdir(parents=True, exist_ok=True)
        self.state_path.write_text(
            json.dumps(state, indent=2, ensure_ascii=False), encoding="utf-8"
        )

    def _reset_state(self):
        self._update_state(status="idle", segment_id="")
        self.evaluator.clear_segment()

